const path = [largest, 11, 28, 41];
const visited = new Set();
let current = 11;
while (current !== 5) {
  if (!visited.has(current)) {
    visited.add(current);
    const next = path.shift();
    if (next === 5) {
      return true;
    }
    current = next;
  } else {
    current++;
  }
}
return false;
